package edu.bvb.campus;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;

@Service
class EngineService {
 final UserRepo users; final TechRepo techs; final CategoryRepo categories; final SubcategoryRepo subs;
 final RequestRepo requests; final AssignmentRepo assignments; final EventRepo events;
 final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder();
 final ConcurrentMap<String,Long> tokens=new ConcurrentHashMap<>();
 final ReentrantLock allocationLock=new ReentrantLock(true);
 EngineService(UserRepo u,TechRepo t,CategoryRepo c,SubcategoryRepo s,RequestRepo r,AssignmentRepo a,EventRepo e){users=u;techs=t;categories=c;subs=s;requests=r;assignments=a;events=e;}
 AppUser login(String username,String password){AppUser u=users.findByUsername(username).orElseThrow(()->new RuntimeException("Invalid username or password"));if(!u.enabled||!encoder.matches(password,u.passwordHash))throw new RuntimeException("Invalid username or password");return u;}
 String issue(AppUser user){String token=UUID.randomUUID().toString();tokens.put(token,user.id);return token;}
 AppUser principal(String token){if(token==null||!tokens.containsKey(token))throw new RuntimeException("Sign in required");return users.findById(tokens.get(token)).orElseThrow();}
 void require(AppUser u,Role... allowed){if(Arrays.stream(allowed).noneMatch(x->x==u.role))throw new RuntimeException("Access denied");}
 @Transactional ServiceRequest submit(AppUser actor,RequestInput in){require(actor,Role.REQUESTER);if(in.title()==null||in.title().isBlank()||in.description()==null||in.description().isBlank()||in.location()==null||in.location().isBlank())throw new RuntimeException("Complete the required fields");var cat=categories.findById(in.categoryId()).orElseThrow();var sub=subs.findById(in.subcategoryId()).orElseThrow();if(!cat.active||!sub.active||!Objects.equals(sub.category.id,cat.id))throw new RuntimeException("Choose an active category and subcategory");ServiceRequest r=new ServiceRequest();r.requester=actor;r.category=cat;r.subcategory=sub;r.title=in.title().trim();r.description=in.description().trim();r.location=in.location().trim();r.priority=in.priority()==null?sub.defaultPriority:in.priority();r.status=RequestStatus.QUEUED;r=requests.save(r);Long id=r.id;events.save(new StatusEvent(r,actor,null,RequestStatus.QUEUED,"Request submitted and queued"));users.findByRole(Role.ADMIN).stream().findFirst().ifPresent(admin->allocate(id,admin));return requests.findById(id).orElseThrow();}
 @Transactional ServiceAssignment allocate(long requestId,AppUser actor){require(actor,Role.ADMIN);allocationLock.lock();try{ServiceRequest r=requests.lockById(requestId).orElseThrow();if(r.status!=RequestStatus.QUEUED&&r.status!=RequestStatus.SUBMITTED)throw new RuntimeException("Request is not waiting for assignment");List<AppUser> candidates=users.findByRole(Role.TECHNICIAN).stream().filter(x->x.enabled).filter(x->{var p=techs.findById(x.id).orElse(null);if(p==null||!p.available||!p.skills.contains(r.subcategory.skill)||!p.locations.contains(r.location))return false;return assignments.countByTechnicianIdAndRequestStatusIn(x.id,List.of(RequestStatus.ASSIGNED,RequestStatus.ACCEPTED,RequestStatus.IN_PROGRESS))<p.maxActive;}).toList();if(candidates.isEmpty()){r.status=RequestStatus.QUEUED;requests.save(r);return null;}for(AppUser chosen:candidates.stream().sorted(Comparator.comparingLong(x->assignments.countByTechnicianIdAndRequestStatusIn(x.id,List.of(RequestStatus.ASSIGNED,RequestStatus.ACCEPTED,RequestStatus.IN_PROGRESS)))).toList()){TechnicianProfile locked=techs.lockByUserId(chosen.id).orElse(null);if(locked==null||!locked.available||!chosen.enabled)continue;long workload=assignments.countByTechnicianIdAndRequestStatusIn(chosen.id,List.of(RequestStatus.ASSIGNED,RequestStatus.ACCEPTED,RequestStatus.IN_PROGRESS));if(workload>=locked.maxActive)continue;ServiceAssignment a=new ServiceAssignment();a.request=r;a.technician=chosen;assignments.saveAndFlush(a);RequestStatus old=r.status;r.status=RequestStatus.ASSIGNED;requests.save(r);events.save(new StatusEvent(r,actor,old,r.status,"Assigned to "+chosen.displayName));return a;}r.status=RequestStatus.QUEUED;requests.save(r);return null;}finally{allocationLock.unlock();}}
 @Transactional ServiceRequest changeStatus(long requestId,RequestStatus next,String note,AppUser actor){ServiceRequest r=requests.lockById(requestId).orElseThrow();boolean permitted=actor.role==Role.ADMIN||(actor.role==Role.REQUESTER&&Objects.equals(r.requester.id,actor.id))||(actor.role==Role.TECHNICIAN&&assignments.findByRequestId(requestId).map(a->Objects.equals(a.technician.id,actor.id)).orElse(false));if(!permitted)throw new RuntimeException("Access denied");RequestStatus from=r.status;if(actor.role==Role.REQUESTER)throw new RuntimeException("Requesters can view status but cannot change it");boolean valid=(from==RequestStatus.ASSIGNED&&next==RequestStatus.ACCEPTED)||(from==RequestStatus.ACCEPTED&&next==RequestStatus.IN_PROGRESS)||(from==RequestStatus.IN_PROGRESS&&next==RequestStatus.COMPLETED)||(actor.role==Role.ADMIN&&next==RequestStatus.CANCELLED&&from!=RequestStatus.COMPLETED);if(!valid)throw new RuntimeException("That status change is not allowed");r.status=next;requests.save(r);events.save(new StatusEvent(r,actor,from,next,note==null?"Status updated":note));return r;}
 List<ServiceRequest> visibleRequests(AppUser actor){return actor.role==Role.ADMIN?requests.findAllByOrderByCreatedAtDesc():actor.role==Role.REQUESTER?requests.findByRequesterIdOrderByCreatedAtDesc(actor.id):assignments.findAll().stream().filter(a->Objects.equals(a.technician.id,actor.id)).map(a->a.request).sorted(Comparator.comparing(x->x.createdAt,Comparator.reverseOrder())).toList();}
 void seed(){if(users.count()>0)return;users.save(new AppUser("admin","Campus Administrator",encoder.encode("Admin@123"),Role.ADMIN));AppUser student=users.save(new AppUser("student","Aarav Student",encoder.encode("Student@123"),Role.REQUESTER));users.save(new AppUser("faculty","Dr. Meera Rao",encoder.encode("Faculty@123"),Role.REQUESTER));users.save(new AppUser("staff","Campus Staff",encoder.encode("Staff@123"),Role.REQUESTER));AppUser e=users.save(new AppUser("tech.electrical","Ravi Electrical",encoder.encode("Tech@123"),Role.TECHNICIAN));techs.save(new TechnicianProfile(e.id,"Electrical,Power","Main Block,Library,Hostel"));AppUser p=users.save(new AppUser("tech.plumbing","Sana Plumbing",encoder.encode("Tech@123"),Role.TECHNICIAN));techs.save(new TechnicianProfile(p.id,"Plumbing,Water","Main Block,Library,Hostel"));var electrical=categories.save(new ServiceCategory("Electrical"));var plumbing=categories.save(new ServiceCategory("Plumbing"));var facilities=categories.save(new ServiceCategory("Facilities"));var power=subs.save(new ServiceSubcategory("Power / lighting",electrical,"Electrical",Priority.HIGH));var leak=subs.save(new ServiceSubcategory("Water leak",plumbing,"Plumbing",Priority.HIGH));subs.save(new ServiceSubcategory("Furniture repair",facilities,"Carpentry",Priority.MEDIUM));subs.save(new ServiceSubcategory("Network / AV",facilities,"IT Support",Priority.MEDIUM));
   demoRequest(student,electrical,power,"Library study light is out","Ceiling light near the second-floor reading tables is not working.","Library",Priority.HIGH,RequestStatus.ASSIGNED,e);
   demoRequest(student,plumbing,leak,"Water fountain is leaking","Water is pooling beside the ground-floor fountain.","Main Block",Priority.MEDIUM,RequestStatus.IN_PROGRESS,p);
 }
 private void demoRequest(AppUser requester,ServiceCategory category,ServiceSubcategory sub,String title,String description,String location,Priority priority,RequestStatus state,AppUser technician){ServiceRequest r=new ServiceRequest();r.requester=requester;r.category=category;r.subcategory=sub;r.title=title;r.description=description;r.location=location;r.priority=priority;r.status=RequestStatus.QUEUED;r=requests.save(r);events.save(new StatusEvent(r,requester,null,RequestStatus.QUEUED,"Request submitted and queued"));ServiceAssignment assignment=new ServiceAssignment();assignment.request=r;assignment.technician=technician;assignments.save(assignment);RequestStatus prior=RequestStatus.QUEUED;r.status=RequestStatus.ASSIGNED;requests.save(r);events.save(new StatusEvent(r,users.findByUsername("admin").orElseThrow(),prior,r.status,"Assigned to "+technician.displayName));if(state==RequestStatus.IN_PROGRESS){events.save(new StatusEvent(r,technician,r.status,RequestStatus.ACCEPTED,"Technician accepted the request"));events.save(new StatusEvent(r,technician,RequestStatus.ACCEPTED,RequestStatus.IN_PROGRESS,"Work is in progress"));r.status=RequestStatus.IN_PROGRESS;requests.save(r);}}
}
record RequestInput(String title,String description,String location,Long categoryId,Long subcategoryId,Priority priority){}
record LoginInput(String username,String password){}
record StatusInput(RequestStatus status,String note){}
record ResetInput(String password){}
